        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the incorrect error handling in the `nfp_pci_probe` function, where it returns `0` instead of the appropriate error code `-EINVAL` when the number of virtual functions (`num_vfs`) exceeds the maximum supported limit (`limit_vfs`). This can lead to ambiguous behavior, as a return value of `0` typically indicates success, while it should indicate an error condition instead.

        Commit message:
        nfp: fix error return code in nfp_pci_probe()

Fix to return error code -EINVAL instead of 0 when num_vfs above
limit_vfs, as done elsewhere in this function.

Fixes: 0dc786219186 ("nfp: handle SR-IOV already enabled when driver is probing")
Signed-off-by: Wei Yongjun <weiyongjun1@huawei.com>
Acked-by: Jakub Kicinski <jakub.kicinski@netronome.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static int nfp_pci_probe(struct pci_dev *pdev,
 			 const struct pci_device_id *pci_id)
 {
 	struct devlink *devlink;
 	struct nfp_pf *pf;
 	int err;

 	err = pci_enable_device(pdev);
 	if (err < 0)
 		return err;

 	pci_set_master(pdev);

 	err = dma_set_mask_and_coherent(&pdev->dev,
 					DMA_BIT_MASK(NFP_NET_MAX_DMA_BITS));
 	if (err)
 		goto err_pci_disable;

 	err = pci_request_regions(pdev, nfp_driver_name);
 	if (err < 0) {
 		dev_err(&pdev->dev, "Unable to reserve pci resources.\n");
 		goto err_pci_disable;
 	}

 	devlink = devlink_alloc(&nfp_devlink_ops, sizeof(*pf));
 	if (!devlink) {
 		err = -ENOMEM;
 		goto err_rel_regions;
 	}
 	pf = devlink_priv(devlink);
 	INIT_LIST_HEAD(&pf->vnics);
 	INIT_LIST_HEAD(&pf->ports);
 	mutex_init(&pf->lock);
 	pci_set_drvdata(pdev, pf);
 	pf->pdev = pdev;

 	pf->wq = alloc_workqueue("nfp-%s", 0, 2, pci_name(pdev));
 	if (!pf->wq) {
 		err = -ENOMEM;
 		goto err_pci_priv_unset;
 	}

 	pf->cpp = nfp_cpp_from_nfp6000_pcie(pdev);
 	if (IS_ERR_OR_NULL(pf->cpp)) {
 		err = PTR_ERR(pf->cpp);
 		if (err >= 0)
 			err = -ENOMEM;
 		goto err_disable_msix;
 	}

 	pf->hwinfo = nfp_hwinfo_read(pf->cpp);

 	dev_info(&pdev->dev, "Assembly: %s%s%s-%s CPLD: %s\n",
 		 nfp_hwinfo_lookup(pf->hwinfo, "assembly.vendor"),
 		 nfp_hwinfo_lookup(pf->hwinfo, "assembly.partno"),
 		 nfp_hwinfo_lookup(pf->hwinfo, "assembly.serial"),
 		 nfp_hwinfo_lookup(pf->hwinfo, "assembly.revision"),
 		 nfp_hwinfo_lookup(pf->hwinfo, "cpld.version"));

 	err = nfp_pf_board_state_wait(pf);
 	if (err)
 		goto err_hwinfo_free;

 	err = nfp_nsp_init(pdev, pf);
 	if (err)
 		goto err_hwinfo_free;

 	pf->mip = nfp_mip_open(pf->cpp);
 	pf->rtbl = __nfp_rtsym_table_read(pf->cpp, pf->mip);

 	pf->dump_flag = NFP_DUMP_NSP_DIAG;
 	pf->dumpspec = nfp_net_dump_load_dumpspec(pf->cpp, pf->rtbl);

 	err = nfp_pcie_sriov_read_nfd_limit(pf);
 	if (err)
 		goto err_fw_unload;

 	pf->num_vfs = pci_num_vf(pdev);
 	if (pf->num_vfs > pf->limit_vfs) {
 		dev_err(&pdev->dev,
 			"Error: %d VFs already enabled, but loaded FW can only support %d\n",
 			pf->num_vfs, pf->limit_vfs);
+		err = -EINVAL;
 		goto err_fw_unload;
 	}

 	err = nfp_net_pci_probe(pf);
 	if (err)
 		goto err_sriov_unlimit;

 	err = nfp_hwmon_register(pf);
 	if (err) {
 		dev_err(&pdev->dev, "Failed to register hwmon info\n");
 		goto err_net_remove;
 	}

 	return 0;

 err_net_remove:
 	nfp_net_pci_remove(pf);
 err_sriov_unlimit:
 	pci_sriov_set_totalvfs(pf->pdev, 0);
 err_fw_unload:
 	kfree(pf->rtbl);
 	nfp_mip_close(pf->mip);
 	if (pf->fw_loaded)
 		nfp_fw_unload(pf);
 	kfree(pf->eth_tbl);
 	kfree(pf->nspi);
 	vfree(pf->dumpspec);
 err_hwinfo_free:
 	kfree(pf->hwinfo);
 	nfp_cpp_free(pf->cpp);
 err_disable_msix:
 	destroy_workqueue(pf->wq);
 err_pci_priv_unset:
 	pci_set_drvdata(pdev, NULL);
 	mutex_destroy(&pf->lock);
 	devlink_free(devlink);
 err_rel_regions:
 	pci_release_regions(pdev);
 err_pci_disable:
 	pci_disable_device(pdev);

 	return err;
 }



